package io.invenlio.procurement;import io.swagger.v3.oas.annotations.Operation;import io.swagger.v3.oas.annotations.security.SecurityRequirement;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import java.time.*;import java.util.*;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/v1/purchase-orders")@SecurityRequirement(name="bearerAuth")class PurchaseOrderController{private final PurchaseOrderService service;PurchaseOrderController(PurchaseOrderService s){service=s;}@Operation(summary="Create a draft purchase order",description="Generates a tenant-safe PO number and snapshots supplier and warehouse identity. No inventory changes occur.")@PostMapping PurchaseOrderService.OrderView create(@Valid@RequestBody Create r){return service.create(r.command());}@Operation(summary="List purchase orders",description="Bounded tenant-scoped summary/detail results with allow-listed sorting.")@GetMapping List<PurchaseOrderService.OrderView>list(@RequestParam(required=false)String poNumber,@RequestParam(required=false)UUID supplierId,@RequestParam(required=false)UUID warehouseId,@RequestParam(required=false)String status,@RequestParam(required=false)LocalDate createdFrom,@RequestParam(required=false)LocalDate createdTo,@RequestParam(required=false)LocalDate expectedFrom,@RequestParam(required=false)LocalDate expectedTo,@RequestParam(required=false)String q,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size,@RequestParam(required=false)String sort){return service.list(poNumber,supplierId,warehouseId,status,createdFrom,createdTo,expectedFrom,expectedTo,q,page,size,sort);}@GetMapping("/{id}")PurchaseOrderService.OrderView get(@PathVariable UUID id){return service.get(id);}@Operation(summary="Update a draft PO header")@PatchMapping("/{id}")PurchaseOrderService.OrderView update(@PathVariable UUID id,@Valid@RequestBody Update r){return service.update(id,r.command(),r.version);}
 @PostMapping("/{id}/lines")PurchaseOrderService.LineView add(@PathVariable UUID id,@Valid@RequestBody LineCreate r){return service.addLine(id,r.command());}@PatchMapping("/{id}/lines/{lineId}")PurchaseOrderService.LineView lineUpdate(@PathVariable UUID id,@PathVariable UUID lineId,@Valid@RequestBody LineUpdate r){return service.updateLine(id,lineId,r.command(),r.version);}@DeleteMapping("/{id}/lines/{lineId}")void remove(@PathVariable UUID id,@PathVariable UUID lineId,@RequestParam long version){service.removeLine(id,lineId,version);}
 @Operation(summary="Submit a non-empty draft PO")@PostMapping("/{id}/submit")PurchaseOrderService.OrderView submit(@PathVariable UUID id,@RequestBody Version r){return service.submit(id,r.version);}@Operation(summary="Approve a submitted PO",description="Requires purchase-order:approve.")@PostMapping("/{id}/approve")PurchaseOrderService.OrderView approve(@PathVariable UUID id,@RequestBody Version r){return service.approve(id,r.version);}@Operation(summary="Mark an approved PO as sent",description="Administrative acknowledgement only; no email is sent.")@PostMapping("/{id}/mark-sent")PurchaseOrderService.OrderView sent(@PathVariable UUID id,@RequestBody Version r){return service.sent(id,r.version);}@Operation(summary="Cancel a PO without deleting it")@PostMapping("/{id}/cancel")PurchaseOrderService.OrderView cancel(@PathVariable UUID id,@Valid@RequestBody Cancel r){return service.cancel(id,r.version,r.reason);}
 record Create(@NotNull UUID supplierId,@NotNull UUID warehouseId,String currency,LocalDate expectedDeliveryDate,@Size(max=120)String supplierReference,@Size(max=1000)String internalNote,@Size(max=1000)String supplierNote){PurchaseOrderService.Create command(){return new PurchaseOrderService.Create(supplierId,warehouseId,currency,expectedDeliveryDate,supplierReference,internalNote,supplierNote);}}record Update(@NotNull UUID warehouseId,LocalDate expectedDeliveryDate,@Size(max=120)String supplierReference,@Size(max=1000)String internalNote,@Size(max=1000)String supplierNote,@PositiveOrZero long version){PurchaseOrderService.Update command(){return new PurchaseOrderService.Update(warehouseId,expectedDeliveryDate,supplierReference,internalNote,supplierNote);}}record LineCreate(@NotNull UUID supplierProductId,@NotBlank String orderedQuantity,LocalDate expectedDeliveryDate){PurchaseOrderService.LineCommand command(){return new PurchaseOrderService.LineCommand(supplierProductId,orderedQuantity,expectedDeliveryDate);}}record LineUpdate(@NotBlank String orderedQuantity,LocalDate expectedDeliveryDate,@PositiveOrZero long version){PurchaseOrderService.LineUpdate command(){return new PurchaseOrderService.LineUpdate(orderedQuantity,expectedDeliveryDate);}}record Version(@PositiveOrZero long version){}record Cancel(@PositiveOrZero long version,@NotBlank@Size(max=500)String reason){}
}
